import{_ as d,o as e,c as o,O as r}from"./chunks/framework.57749cb7.js";const g=JSON.parse('{"title":"操作系统基础","description":"操作系统基础：进程/线程/协程、调度与上下文切换、虚拟内存与 RSS/VSS/PSS、文件系统、五种 IO 模型与零拷贝，以及每个概念对应的观测命令和 Java 世界的映射。","frontmatter":{"description":"操作系统基础：进程/线程/协程、调度与上下文切换、虚拟内存与 RSS/VSS/PSS、文件系统、五种 IO 模型与零拷贝，以及每个概念对应的观测命令和 Java 世界的映射。","tags":["计算机基础","操作系统","并发编程"]},"headers":[],"relativePath":"cs/操作系统基础.md","filePath":"cs/操作系统基础.md","lastUpdated":1793330791000}'),a={name:"cs/操作系统基础.md"};function s(c,t,n,l,i,h){return e(),o("div",null,t[0]||(t[0]=[r(`<h1 id="操作系统基础" tabindex="-1">操作系统基础 <a class="header-anchor" href="#操作系统基础" aria-label="Permalink to &quot;操作系统基础&quot;">​</a></h1><blockquote><p>你写的高并发、JVM、锁，全都建立在操作系统的这几个概念上。 这篇不只讲「为什么」，还给了<strong>每个概念对应的观测命令</strong> —— 知道概念却不会查，等于不会。</p></blockquote><h2 id="一、进程-vs-线程-vs-协程" tabindex="-1">一、进程 vs 线程 vs 协程 <a class="header-anchor" href="#一、进程-vs-线程-vs-协程" aria-label="Permalink to &quot;一、进程 vs 线程 vs 协程&quot;">​</a></h2><table><thead><tr><th></th><th>进程</th><th>线程</th><th>协程</th></tr></thead><tbody><tr><td>资源</td><td><strong>资源分配的基本单位</strong>（独立地址空间）</td><td>共享进程内存</td><td>共享线程栈</td></tr><tr><td>调度</td><td>进程级调度</td><td><strong>CPU 调度的基本单位</strong></td><td>用户态调度（无需内核）</td></tr><tr><td>开销</td><td>创建销毁重</td><td>较轻（约 1~10 微秒级切换）</td><td><strong>极轻</strong>（纳秒级切换）</td></tr><tr><td>隔离</td><td>强（一个进程崩不影响别人）</td><td>弱（共享内存，一个崩可能全崩）</td><td>弱</td></tr></tbody></table><p><strong>一句话</strong>：进程是「有自己房子的人」，线程是「房子里的人」，协程是「人手里同时做的几件事」。</p><p><strong>为什么线程切换比进程快</strong>：进程切换要换页表、清 TLB；线程切换只换栈和寄存器（共享地址空间）。</p><blockquote><p>Java 的 <code>Thread</code> 在 JDK 21 之前是<strong>1:1 映射到内核线程</strong>；JDK 21 的虚拟线程是 M:N（大量虚拟线程跑在少量载体线程上），见 <a href="/cao_note/backend/Java/06-JUC并发编程">JUC 并发编程</a>。</p></blockquote><h2 id="二、进程状态与调度" tabindex="-1">二、进程状态与调度 <a class="header-anchor" href="#二、进程状态与调度" aria-label="Permalink to &quot;二、进程状态与调度&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">新建 → 就绪 ⇄ 运行 → 终止</span></span>
<span class="line"><span style="color:#e1e4e8;">         ↑        ↓</span></span>
<span class="line"><span style="color:#e1e4e8;">         └─ 阻塞 ←─（等待 IO / 锁）</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">新建 → 就绪 ⇄ 运行 → 终止</span></span>
<span class="line"><span style="color:#24292e;">         ↑        ↓</span></span>
<span class="line"><span style="color:#24292e;">         └─ 阻塞 ←─（等待 IO / 锁）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table><thead><tr><th>算法</th><th>特点</th><th>问题</th></tr></thead><tbody><tr><td>FCFS（先来先服务）</td><td>简单</td><td>长任务拖死后面（护航效应）</td></tr><tr><td>SJF（短作业优先）</td><td>平均等待最短</td><td>长任务可能饿死</td></tr><tr><td>时间片轮转（RR）</td><td>公平</td><td>时间片太大=退化成 FCFS，太小=切换开销大</td></tr><tr><td>多级反馈队列</td><td>现代系统主流（Linux 的 CFS 近似）</td><td>实现复杂</td></tr></tbody></table><p><strong>上下文切换的代价</strong>：保存寄存器/栈，恢复下一个，通常 <strong>2~10 微秒</strong>。看起来很小，但每秒切几万次就是几十毫秒的开销 —— 这是「多线程不一定更快」的根源，也是 <code>top</code> 里 <code>sy</code>（内核态）特别高的常见原因。</p><p><strong>怎么观测</strong>：<code>vmstat 1</code> 的 <code>cs</code> 列（每秒上下文切换次数）、<code>pidstat -w 1</code>（每个进程的 cswch/nvcswch）。</p><h2 id="三、线程同步" tabindex="-1">三、线程同步 <a class="header-anchor" href="#三、线程同步" aria-label="Permalink to &quot;三、线程同步&quot;">​</a></h2><table><thead><tr><th>原语</th><th>作用</th></tr></thead><tbody><tr><td><strong>互斥锁（Mutex）</strong></td><td>互斥访问临界区</td></tr><tr><td><strong>信号量（Semaphore）</strong></td><td>控制同时访问的数量（可以 &gt;1）</td></tr><tr><td><strong>条件变量（CondVar）</strong></td><td>等待某个条件成立（配合锁用）</td></tr><tr><td><strong>读写锁</strong></td><td>读读并发，写写/读写互斥</td></tr></tbody></table><p><strong>死锁四条件</strong>（缺一不可）：互斥、持有并等待、不可剥夺、循环等待。破坏任意一个即可避免：</p><ul><li>一次性申请所有资源（破坏持有并等待）</li><li><strong>按固定顺序加锁</strong>（破坏循环等待，最实用）</li><li><code>tryLock</code> 带超时（破坏不可剥夺）</li></ul><p><strong>怎么观测</strong>：<code>jstack</code> 能直接报 <code>Found one Java-level deadlock</code>；系统级用 <code>cat /proc/&lt;pid&gt;/stack</code>、<code>gdb</code> 抓线程栈。</p><h2 id="四、虚拟内存与分页" tabindex="-1">四、虚拟内存与分页 <a class="header-anchor" href="#四、虚拟内存与分页" aria-label="Permalink to &quot;四、虚拟内存与分页&quot;">​</a></h2><h3 id="为什么需要虚拟内存" tabindex="-1">为什么需要虚拟内存 <a class="header-anchor" href="#为什么需要虚拟内存" aria-label="Permalink to &quot;为什么需要虚拟内存&quot;">​</a></h3><p>每个进程都以为「我独占整个内存」，其实靠操作系统把虚拟地址映射到物理地址。好处：</p><ol><li><strong>隔离</strong>：一个进程读不到别的进程的内存；</li><li><strong>省内存</strong>：不同进程共享同一份只读代码（如 libc）；</li><li><strong>简化链接</strong>：程序可以从固定地址开始加载。</li></ol><h3 id="分页与页表" tabindex="-1">分页与页表 <a class="header-anchor" href="#分页与页表" aria-label="Permalink to &quot;分页与页表&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">虚拟地址 = 页号 + 页内偏移</span></span>
<span class="line"><span style="color:#e1e4e8;">页表：页号 → 物理页框号</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">虚拟地址 = 页号 + 页内偏移</span></span>
<span class="line"><span style="color:#24292e;">页表：页号 → 物理页框号</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><strong>页</strong>：内存管理的最小单位（通常 4KB）。</li><li><strong>页表</strong>：进程级，太大 → <strong>多级页表</strong>（只给用到的地址建表）。</li><li><strong>TLB</strong>：页表的缓存（在 CPU 里），命中就不查页表 —— 这就是「进程切换慢」的原因（TLB 要刷）。</li></ul><h3 id="三个内存指标必须分清" tabindex="-1">三个内存指标必须分清 <a class="header-anchor" href="#三个内存指标必须分清" aria-label="Permalink to &quot;三个内存指标必须分清&quot;">​</a></h3><table><thead><tr><th>指标</th><th>含义</th><th>排查时怎么用</th></tr></thead><tbody><tr><td><strong>VSS</strong>（Virtual Set Size）</td><td>进程申请的<strong>虚拟内存总量</strong></td><td>通常很大（含未使用、共享库、预留），<strong>几乎没有参考价值</strong></td></tr><tr><td><strong>RSS</strong>（Resident Set Size）</td><td>实际占用的<strong>物理内存</strong></td><td>最常用，但<strong>共享库被重复计算</strong>（10 个进程用同一个 lib，每个都算一份）</td></tr><tr><td><strong>PSS</strong>（Proportional Set Size）</td><td>共享内存按比例分摊后的实际占用</td><td><strong>最准</strong>，<code>smem</code> 才能看到</td></tr></tbody></table><blockquote><p>典型误区：<code>ps</code> 看到的 RSS 加起来远超物理内存 —— 不是内存泄漏，是共享页被重复计数了。</p></blockquote><h3 id="缺页中断" tabindex="-1">缺页中断 <a class="header-anchor" href="#缺页中断" aria-label="Permalink to &quot;缺页中断&quot;">​</a></h3><p>访问的页不在物理内存 → 触发缺页中断 → 从磁盘换入。<strong>频繁缺页 = 抖动</strong>（thrashing），说明物理内存不够或程序局部性差。</p><p><strong>怎么观测</strong>：<code>vmstat 1</code> 的 <code>si</code>/<code>so</code>（换入换出，持续 &gt;0 就危险）、<code>pidstat -r 1</code> 的 majflt（主缺页，要从磁盘读）。</p><h2 id="五、文件系统" tabindex="-1">五、文件系统 <a class="header-anchor" href="#五、文件系统" aria-label="Permalink to &quot;五、文件系统&quot;">​</a></h2><table><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>inode</td><td>文件的元数据（权限、大小、数据块位置），不含文件名</td></tr><tr><td>文件名</td><td>目录项里「名字 → inode」的映射</td></tr><tr><td>软链接</td><td>指向<strong>路径</strong>（可跨文件系统，删原文件就断）</td></tr><tr><td>硬链接</td><td>指向<strong>同一个 inode</strong>（删一个名字，数据还在）</td></tr><tr><td>页缓存（page cache）</td><td>文件 IO 走内核缓存，写有延迟 —— <code>fsync</code> 才落盘</td></tr></tbody></table><p><strong>两个高频现象</strong>：</p><ol><li><strong><code>rm</code> 了文件空间不释放</strong>：进程还开着这个 inode，要等它关闭。<code>lsof +L1</code> 能看到。</li><li><strong><code>free</code> 显示内存快满了但系统不卡</strong>：那是 page cache，可回收，看 <code>available</code> 而不是 <code>free</code>。</li></ol><h2 id="六、五种-io-模型与零拷贝" tabindex="-1">六、五种 IO 模型与零拷贝 <a class="header-anchor" href="#六、五种-io-模型与零拷贝" aria-label="Permalink to &quot;六、五种 IO 模型与零拷贝&quot;">​</a></h2><table><thead><tr><th>模型</th><th>特点</th><th>例子</th></tr></thead><tbody><tr><td>阻塞 IO</td><td>一直等数据就绪</td><td>传统 <code>read()</code></td></tr><tr><td>非阻塞 IO</td><td>立即返回，自己轮询</td><td><code>O_NONBLOCK</code></td></tr><tr><td><strong>IO 多路复用</strong></td><td>一个线程监听多个 fd</td><td>select / poll / epoll</td></tr><tr><td>信号驱动 IO</td><td>内核发信号通知</td><td>SIGIO</td></tr><tr><td>异步 IO</td><td>内核拷完再回调</td><td>io_uring、AIO</td></tr></tbody></table><p><strong>epoll 为什么快</strong>：注册一次 + 只返回就绪的（回调通知），不像 select 每次全量拷贝并遍历。完整对比见 <a href="/cao_note/backend/Java/07-Java网络编程与NIO">Java NIO</a>。</p><h3 id="零拷贝-后端必问" tabindex="-1">零拷贝（后端必问） <a class="header-anchor" href="#零拷贝-后端必问" aria-label="Permalink to &quot;零拷贝（后端必问）&quot;">​</a></h3><p>普通 <code>read + write</code> 传文件要 <strong>4 次拷贝 + 4 次上下文切换</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">磁盘 → 内核缓冲区 → 用户缓冲区 → socket 缓冲区 → 网卡</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">磁盘 → 内核缓冲区 → 用户缓冲区 → socket 缓冲区 → 网卡</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table><thead><tr><th>方案</th><th>省了什么</th><th>适用</th></tr></thead><tbody><tr><td><code>sendfile</code></td><td>省掉用户态（2 次拷贝）</td><td>静态文件服务（Nginx）</td></tr><tr><td><code>mmap + write</code></td><td>省掉一次拷贝</td><td>大文件、需要改内容</td></tr><tr><td><code>splice</code></td><td>内核管道传递</td><td>代理转发</td></tr></tbody></table><p><strong>Kafka 为什么吞吐高</strong>：大量用到了 <code>sendfile</code> + 页缓存，消费时数据不落用户态。</p><h2 id="七、概念-↔-观测命令对照表" tabindex="-1">七、概念 ↔ 观测命令对照表 <a class="header-anchor" href="#七、概念-↔-观测命令对照表" aria-label="Permalink to &quot;七、概念 ↔ 观测命令对照表&quot;">​</a></h2><p>这张表是这篇最有用的部分：<strong>每个 OS 概念，怎么用命令看到它</strong>。</p><table><thead><tr><th>概念</th><th>命令</th><th>看什么</th></tr></thead><tbody><tr><td>平均负载</td><td><code>uptime</code> / <code>top</code></td><td><code>load average</code>（1/5/15 分钟），&gt; 核数说明排队</td></tr><tr><td>CPU 使用率</td><td><code>top</code>、<code>mpstat -P ALL 1</code></td><td><code>%us</code>（用户态）/<code>%sy</code>（内核态）/<code>%wa</code>（IO 等待）</td></tr><tr><td>哪个线程在吃 CPU</td><td><code>top -Hp &lt;pid&gt;</code></td><td>线程级 CPU，配合 <code>jstack</code> 的 nid</td></tr><tr><td>上下文切换</td><td><code>vmstat 1</code>（cs）、<code>pidstat -w 1</code></td><td>每秒切换次数</td></tr><tr><td>内存总量/可用</td><td><code>free -h</code></td><td>看 <strong>available</strong>，别只看 free</td></tr><tr><td>进程内存</td><td><code>ps aux --sort=-rss</code>、<code>smem -tk</code></td><td>RSS vs PSS</td></tr><tr><td>交换</td><td><code>vmstat 1</code>（si/so）、<code>swapon -s</code></td><td>持续换入换出=内存不足</td></tr><tr><td>缺页</td><td><code>pidstat -r 1</code></td><td>majflt（主缺页，要读磁盘）</td></tr><tr><td>磁盘吞吐/延迟</td><td><code>iostat -xz 1</code></td><td><code>%util</code>（饱和）、<code>await</code>（延迟）</td></tr><tr><td>谁在读写磁盘</td><td><code>iotop -o</code></td><td>进程级 IO</td></tr><tr><td>磁盘空间</td><td><code>df -h</code>、<code>du -sh *</code></td><td>分区用量 / 目录占用</td></tr><tr><td>被删除仍占用的文件</td><td><code>lsof +L1</code></td><td>日志没轮转的典型症状</td></tr><tr><td>网络连接</td><td><code>ss -tanp</code>、<code>ss -s</code></td><td>各状态连接数（TIME_WAIT / ESTAB）</td></tr><tr><td>网络重传/丢包</td><td><code>netstat -s</code>、<code>nstat</code></td><td>retrans、drop</td></tr><tr><td>抓包</td><td><code>tcpdump -i eth0 port 8080 -w x.pcap</code></td><td>握手、重传、RST</td></tr><tr><td>系统调用</td><td><code>strace -p &lt;pid&gt; -T -f</code></td><td>卡在哪个 syscall</td></tr><tr><td>文件句柄</td><td><code>lsof -p &lt;pid&gt;</code>、<code>ulimit -n</code></td><td>句柄泄漏、上限</td></tr><tr><td>内核日志</td><td><code>dmesg -T</code></td><td>OOM Killer、驱动报错</td></tr></tbody></table><h2 id="八、从现象到命令-排查路径" tabindex="-1">八、从现象到命令（排查路径） <a class="header-anchor" href="#八、从现象到命令-排查路径" aria-label="Permalink to &quot;八、从现象到命令（排查路径）&quot;">​</a></h2><table><thead><tr><th>现象</th><th>先跑什么</th><th>常见结论</th></tr></thead><tbody><tr><td><strong>CPU 100%</strong></td><td><code>top</code> → <code>top -Hp</code> → <code>jstack</code> 对 nid</td><td>死循环 / 频繁 GC / 锁竞争</td></tr><tr><td><strong>load 高但 CPU 闲</strong></td><td><code>iostat -xz 1</code></td><td>磁盘 IO 等待（D 状态进程）</td></tr><tr><td><strong>内存持续涨</strong></td><td><code>free -h</code> + <code>smem</code> + <code>jmap -histo:live</code></td><td>泄漏 / page cache / 堆外内存</td></tr><tr><td><strong>进程被 kill</strong></td><td><code>dmesg -T | grep -i oom</code></td><td>OOM Killer 选中了它</td></tr><tr><td><strong>接口变慢</strong></td><td><code>iostat</code> → <code>ss -s</code> → <code>strace -T</code></td><td>磁盘、连接堆积、某个 syscall 阻塞</td></tr><tr><td><strong>连接数打满</strong></td><td><code>ss -s</code>、<code>ulimit -n</code>、<code>sysctl net.core.somaxconn</code></td><td>短连接太多 / backlog 太小</td></tr><tr><td><strong>磁盘写满</strong></td><td><code>df -h</code> → <code>du -sh</code> → <code>lsof +L1</code></td><td>日志、core dump、未释放的删除文件</td></tr></tbody></table><h2 id="九、和-java-世界的对应关系" tabindex="-1">九、和 Java 世界的对应关系 <a class="header-anchor" href="#九、和-java-世界的对应关系" aria-label="Permalink to &quot;九、和 Java 世界的对应关系&quot;">​</a></h2><table><thead><tr><th>OS 概念</th><th>Java 里对应什么</th></tr></thead><tbody><tr><td>进程</td><td>一个 JVM 实例（<code>java -jar</code>）</td></tr><tr><td>内核线程</td><td><code>java.lang.Thread</code>（JDK 21 前 1:1 映射）</td></tr><tr><td>用户态调度</td><td><strong>虚拟线程</strong>（JDK 21，M:N）</td></tr><tr><td>互斥锁 / 条件变量</td><td><code>synchronized</code>、<code>ReentrantLock</code> + <code>Condition</code>（AQS 实现）</td></tr><tr><td>信号量</td><td><code>Semaphore</code></td></tr><tr><td>读写锁</td><td><code>ReentrantReadWriteLock</code>、<code>StampedLock</code></td></tr><tr><td>虚拟内存</td><td>JVM 堆、Metaspace、直接内存（<code>-Xmx</code>、<code>-XX:MaxDirectMemorySize</code>）</td></tr><tr><td>页</td><td>JVM 的**卡表（card table）**用于 GC 跨代引用、堆按 Region 划分</td></tr><tr><td>缺页 / 换页</td><td>堆被 swap 会严重拖慢 GC —— 生产环境应 <code>vm.swappiness=0</code> 或禁用 swap</td></tr><tr><td>epoll</td><td>NIO 的 <code>Selector</code>（Linux 下就是 epoll）</td></tr><tr><td>零拷贝</td><td><code>FileChannel.transferTo</code>（<code>sendfile</code>）、Netty 的 <code>FileRegion</code></td></tr><tr><td>page cache</td><td>读写文件走内核缓存；<code>mmap</code> 映射大文件</td></tr><tr><td>上下文切换</td><td>线程池开太大反而慢；<code>jstack</code> 里大量 <code>BLOCKED</code> 是锁竞争</td></tr></tbody></table><h2 id="十、速查" tabindex="-1">十、速查 <a class="header-anchor" href="#十、速查" aria-label="Permalink to &quot;十、速查&quot;">​</a></h2><table><thead><tr><th>问题</th><th>一句话</th></tr></thead><tbody><tr><td>进程线程区别</td><td>资源分配单位 vs CPU 调度单位</td></tr><tr><td>线程切换为什么快</td><td>共享地址空间，不换页表</td></tr><tr><td>上下文切换代价</td><td>约 2~10 微秒，看 <code>vmstat</code> 的 cs</td></tr><tr><td>死锁四条件</td><td>互斥、持有并等待、不可剥夺、循环等待</td></tr><tr><td>虚拟内存好处</td><td>隔离、共享、简化加载</td></tr><tr><td>RSS / PSS 区别</td><td>RSS 重复计算共享页，PSS 按比例分摊更准</td></tr><tr><td>TLB 是什么</td><td>页表缓存，miss 要查内存页表</td></tr><tr><td>缺页抖动</td><td>内存不够，<code>vmstat</code> 的 si/so 持续为正</td></tr><tr><td>page cache 占满内存</td><td>正常，看 <code>available</code> 不看 <code>free</code></td></tr><tr><td>硬链接 vs 软链接</td><td>同 inode vs 指路径</td></tr><tr><td>零拷贝省了什么</td><td>省掉用户态那次拷贝（sendfile）</td></tr><tr><td>epoll 为什么快</td><td>注册一次 + 就绪回调</td></tr></tbody></table>`,51)]))}const b=d(a,[["render",s]]);export{g as __pageData,b as default};
